use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Extends log `Event`s to provide complete `Metadata`."] # [doc = ""] # [doc = " In `tracing-log`, an `Event` produced by a log (through [`AsTrace`]) has an hard coded"] # [doc = " \"log\" target and no `file`, `line`, or `module_path` attributes. This happens because `Event`"] # [doc = " requires its `Metadata` to be `'static`, while [`log::Record`]s provide them with a generic"] # [doc = " lifetime."] # [doc = ""] # [doc = " However, these values are stored in the `Event`'s fields and"] # [doc = " the [`normalized_metadata`] method allows to build a new `Metadata`"] # [doc = " that only lives as long as its source `Event`, but provides complete"] # [doc = " data."] # [doc = ""] # [doc = " It can typically be used by `Subscriber`s when processing an `Event`,"] # [doc = " to allow accessing its complete metadata in a consistent way,"] # [doc = " regardless of the source of its source."] # [doc = ""] # [doc = " [`normalized_metadata`]: NormalizeEvent#normalized_metadata"] pub trait NormalizeEvent < 'a > : crate :: sealed :: Sealed { # [doc = " If this `Event` comes from a `log`, this method provides a new"] # [doc = " normalized `Metadata` which has all available attributes"] # [doc = " from the original log, including `file`, `line`, `module_path`"] # [doc = " and `target`."] # [doc = " Returns `None` is the `Event` is not issued from a `log`."] fn normalized_metadata (& 'a self) -> Option < Metadata < 'a > > ; # [doc = " Returns whether this `Event` represents a log (from the `log` crate)"] fn is_log (& self) -> bool ; }